-- Classic 1.60 (WoW Forever) world baseline, part 1: the vanilla world (converted from VMaNGOS db-13b49dc), Zephras Isle
-- and every Forever change on top of TDB 1210.26091 + TrinityCore's sql/updates, as plain SQL (classic_re/db_baseline.py).
-- Replaces the files that read a vmangos_world database; safe to run again.
SET FOREIGN_KEY_CHECKS=0;

-- areatrigger: 0 changed, 291 removed of 0 -> whole table
DELETE FROM `areatrigger`;


-- areatrigger_scripts: 23 changed or new, 0 removed

-- areatrigger_teleport: 115 changed, 1 removed of 362 -> whole table
DELETE FROM `areatrigger_teleport`;

-- class_expansion_requirement: 10 changed or new, 0 removed

-- classic_broadcast_text_type: Forever table
CREATE TABLE IF NOT EXISTS `classic_broadcast_text_type` (
  `ID` int unsigned NOT NULL,
  `ChatType` tinyint unsigned NOT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Classic 1.60: VMaNGOS broadcast_text chat types for ClassicScriptText()';

