-- creature_classic_level: Forever table
CREATE TABLE IF NOT EXISTS `creature_classic_level` (
  `entry` int unsigned NOT NULL,
  `level_min` tinyint unsigned NOT NULL,
  `level_max` tinyint unsigned NOT NULL,
  PRIMARY KEY (`entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Classic 1.60: fixed vanilla creature levels (replaces ContentTuning scaling)';

